 SELECT
 '${statusValid}' statusValid,
 '${finprodId}' finprodId,
 '${CASH_TYPE_1_02}' CASH_TYPE_1_02,
 '${CASH_TYPE_2_C02}' CASH_TYPE_2_C02,
 T1.ps cashType,
 T2.PA_BUSS_TYPE,
 T1.CHL_ID,
 /*业务编号*/ T1.TOTLE_TRADE_ID busiCode,
 /*总剩余本金*/ T2.REMAIN_PRIN_AMT qty,
 /*计息开始日 */ to_char(T1.VDATE, 'yyyy-MM-dd') vDate,
 /*计息结束日 */ to_char(T1.MDATE, 'yyyy-MM-dd') mDate,
 /*利息调整 */ t1.FPRICE_AMT-t2.THEORY_PRIN-t2.THEORY_INT intAdjustment,
 /*理论支付日 */ to_char(T2.THEORY_PAY_DATE, 'yyyy-MM-dd') interestPayDay,
 /*还本金额 */ t2.THEORY_PRIN returnAmount,
 /*理论应收利息 */ t2.THEORY_INT intAmtTheory,
 /*实收本息总额 */ t1.FPRICE_AMT fpriceAmt,
 /*税费金额 */ t3.FEE_AMT taxAmount,
 /*到账金额 */ t1.TRADE_AMT arrivalAmt,
 /*资金到账日 */ to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') arrivalDate,
 /*是否结清 */T1.IS_CLEAN,
