 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1
 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID
 LEFT JOIN TRD_TRADE_FEE_DETAIL T3 ON T3.TRADE_ID = T1.TOTLE_TRADE_ID

LEFT JOIN FIN_PRODUCT_ADD FP ON T1.CHL_ID = FP.FINPROD_ID
 where
     T1.TOTLE_TRADE_ID = #{busiCode}
     AND T1.PORTFOLIO_ID IS NULL

/*根据cashId合并还本付息数据*/ select t8.cash_type, t8.CASH_ID, '${statusValid}' statusValid, '${CASH_TYPE_1_02}' CASH_TYPE_1_02, '${CASH_TYPE_2_C02}' CASH_TYPE_2_C02, t8.FINPROD_ID finprodId, t10.FINPROD_MARKET_ID,T8.SEC_ACCT_ID CHL_ID, t10.FINPROD_NAME,
/* 剩余本金 */ ROUND(SUM(T8.QTY), 4) qty,
0 intAdjustment, /* 借款利率 */ MAX(NVL(fccr.YIELD, 0))*100 yield, /*计息开始日 */ to_char(min(t8.VDATE), 'yyyy-MM-dd') vDate, /*计息结束日 */ to_char(t8.MDATE, 'yyyy-MM-dd') mDate, /*理论支付日 */ to_char(t8.PAY_DATE, 'yyyy-MM-dd') interestPayDay, /*还本金额 */ round(sum(nvl(t8.prinAmt, 0)), 4) returnAmount, /*理论本息总额*/ round(sum(nvl(t8.fpriceAmt, 0)), 4) theoryAmt, /*实收本息总额*/ round(sum(nvl(t8.prinAmt, 0) + T8.intAmt), 4) fpriceAmt, /*理论应收利息*/ round(sum(nvl(T8.intAmt, 0)), 4) intAmtTheory, round(sum(nvl(t8.prinAmt, 0) + T8.intAmt), 4) arrivalAmt, CASE WHEN T8.SEC_ACCT_ID= '999999' THEN 0 ELSE 1 END channel, CASE WHEN (SUM(T8.intAmt) IS NULL OR SUM(T8.intAmt)=0)THEN 0 ELSE 1 END intAmtUnpayFlag,/*是否展示累计未付*/ FP.COLLECT_TYPE from (select T7.FINPROD_ID, T7.AMOUNT QTY, SUM(decode(T7.dqprinamt, null, t7.int_prin_amt * T7.AMOUNT/T7.MAX_CASH_BASEAMT, null)) return_amt, T7.PORTFOLIO_ID,T7.SEC_ACCT_ID, /*这一层，同一组合持仓对不用计划，数量不合并*/ listagg(T7.CASH_ID, ',') within GROUP ( ORDER BY T7.CASH_ID) CASH_ID, listagg(T7.CASH_TYPE, ',') within GROUP ( ORDER BY T7.CASH_ID) CASH_TYPE, MIN(T7.VDATE) VDATE, T7.MDATE, SUM(T7.CASH_AMT * T7.AMOUNT/T7.CASH_BASEAMT) fpriceAmt, MAX(T7.INT_PRIN_AMT) INT_PRIN_AMT, /*理论本息总额*/ SUM(T7.PRIN_AMT * T7.AMOUNT/T7.CASH_BASEAMT) prinAmt /*还本金额*/, SUM(T7.INT_AMT/* - t7.payedInt*/) intAmt /*理论利息*/, T7.PAY_DATE from (SELECT T1.FINPROD_ID, T1.PORTFOLIO_ID,T1.SEC_ACCT_ID, T1.AMOUNT AMOUNT, T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, T6.CASH_AMT, t6.INT_PRIN_AMT, T6.PRIN_AMT, case when t6.cash_type in ('04', '01') then 0 else t6.prin_amt end dqprinamt, PSV.TDY_INTINCEXP, T6.CASH_BASEAMT, case when t6.cash_type IN (#{CASH_CLASS_TYPE01}, #{CASH_CLASS_TYPE04}) then NVL(PSV.TDY_INTINCEXP, t6.INT_AMT*T1.AMOUNT/T6.CASH_BASEAMT) WHEN T6.CASH_TYPE IN (#{CASH_CLASS_TYPE02}, #{CASH_CLASS_TYPE03}) AND T6.INT_AMT is not null and T6.INT_AMT != 0 AND PSV.SHARE_AMT is not null THEN ROUND(T6.PRIN_AMT * T1.AMOUNT/T6.CASH_BASEAMT * PSV.TDY_INTINCEXP/PSV.SHARE_AMT, 2) else t6.INT_AMT * T1.AMOUNT/t6.CASH_BASEAMT end INT_AMT, t6.PAY_DATE, MAX(FCP11.CASH_BASEAMT) MAX_CASH_BASEAMT from PTL_SEC_POSITION T1 INNER JOIN (select T2.CASH_TYPE, T2.CASH_ID, T2.VDATE, T2.MDATE, T2.CASH_AMT, T2.INT_PRIN_AMT, T2.PRIN_AMT, T2.CASH_BASEAMT, nvl(T2.INT_AMT,0)-nvl(T2.REPAY_WITHOUT_INT,0) INT_AMT, t2.PAY_DATE, T2.FINPROD_ID from FIN_CASH_PLAN T2 WHERE T2.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17} AND T2.FINPROD_ID = #{finprodId} AND T2.MDATE = to_date(#{mDate}, 'yyyy-MM-dd') and T2.CASH_TYPE IN (#{CASH_CLASS_TYPE01},#{CASH_CLASS_TYPE02},#{CASH_CLASS_TYPE03},#{CASH_CLASS_TYPE04}) and (t2.INT_AMT > 0 or t2.PRIN_AMT > 0)
) T6 ON T1.FINPROD_ID = T6.FINPROD_ID AND T1.HODING_TYPE = #{POSITION_TYPE03} AND t1.CDATE < t6.MDATE and T1.AMOUNT > 0
AND T1.SEC_ACCT_ID = #{chlId}
LEFT JOIN PTL_SEC_VALUTION PSV ON T6.MDATE = PSV.CDATE + 1 AND T1.PORTFOLIO_ID = PSV.PORTFOLIO_ID AND T1.FINPROD_ID = PSV.FINPROD_ID AND PSV.INV_AIM = '999999' INNER JOIN FIN_CASH_PLAN FCP11 ON T6.FINPROD_ID = FCP11.FINPROD_ID inner join PTL_PORTFOLIO pp on T1.PORTFOLIO_ID = pp.PORTFOLIO_ID where NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.IS_CANCEL = #{YESNO_N} and T6.MDATE = TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND ((TPDA.CHL_ID is NULL and t1.sec_acct_id='999999') OR TPDA.CHL_ID = T1.SEC_ACCT_ID))
/*不存在流程中的当期或之前的交易*/ AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.IS_CANCEL = #{YESNO_N} and T6.MDATE >= TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND ((TPDA.CHL_ID is NULL and t1.sec_acct_id='999999') OR TPDA.CHL_ID = T1.SEC_ACCT_ID))
AND NOT EXISTS ( SELECT 1 FROM PTL_SEC_POSITION tpsp where tpsp.HODING_TYPE = #{POSITION_TYPE03} and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID and tpsp.FINPROD_ID = T1.FINPROD_ID and tpsp.CDATE > T1.CDATE and tpsp.CDATE < T6.MDATE ) and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'
and T1.PORTFOLIO_ID group by T1.FINPROD_ID, T1.PORTFOLIO_ID,T1.SEC_ACCT_ID, T1.AMOUNT, T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, T6.CASH_AMT, t6.INT_PRIN_AMT, T6.PRIN_AMT, PSV.TDY_INTINCEXP, T6.CASH_BASEAMT,PSV.TDY_INTINCEXP, t6.INT_AMT,PSV.SHARE_AMT, t6.PAY_DATE ) T7 GROUP BY T7.FINPROD_ID, T7.AMOUNT, T7.MDATE, T7.PORTFOLIO_ID,T7.SEC_ACCT_ID, T7.PAY_DATE ) T8 LEFT JOIN FIN_PRODUCT T10 ON T10.FINPROD_ID = T8.FINPROD_ID LEFT JOIN FIN_CASH_CALC_RULE fccr ON instr(t8.CASH_ID, fccr.CASH_ID) > 0 AND fccr.EFF_DATE <= t8.MDATE
LEFT JOIN FIN_PRODUCT_ADD FP ON T8.SEC_ACCT_ID = FP.FINPROD_ID WHERE NOT EXISTS(SELECT 1 FROM FIN_CASH_CALC_RULE T6 WHERE fccr.CASH_ID = T6.CASH_ID AND T6.EFF_DATE <= T8.MDATE AND T6.EFF_DATE > fccr.EFF_DATE ) and T10.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17} AND T10.FINPROD_ID = #{finprodId} group by t8.FINPROD_ID, t10.FINPROD_MARKET_ID,T8.SEC_ACCT_ID, t10.FINPROD_NAME, CASE WHEN (T8.intAmt IS NULL OR T8.intAmt =0) THEN 0 ELSE 1 END, /*计息结束日 */ t8.MDATE, /*理论支付日 */ t8.PAY_DATE, t8.cash_type, t8.CASH_ID, FP.COLLECT_TYPE

mapper.select:
SELECT T1.TOTLE_TRADE_ID TRADE_ID, T1.BUSI_TYPE, T1.FINPROD_ID, T1.FINPROD_TYPE, T1.FINPROD_TYPE2, T1.BRANCH, T1.TRADE_DATE, T1.VDATE, T1.MDATE, T1.SETTLE_DATE, T1.CCY, T1.UNIT_CPRICE, T1.UNIT_INT, T1.UNIT_FPRICE, T1.PAR_VALUE, T1.CPRICE_AMT, T1.SHARE_AMT, T1.PRIN_AMT, T1.INT_AMT, T1.FPRICE_AMT, T1.FEE_AMT_PAY, T1.TRADE_AMT, T1.FEE_AMT_UNPAY, T1.FEE_AMT, T1.PS, T1.YIELD, T1.EXER_YIELD, T1.INV_AIM, T1.TRADE_STATUS, T1.IS_CANCEL, T1.P_TRADE_ID, T1.IS_CLEAN, T1.TOTLE_TRADE_ID, T1.B_TRADE_ID, T1.CHL_ID, T1.COUNTER_ID, T1.IS_OUT_TRADE, T1.TRADE_MARKET, T1.TRADE_PLAT, T1.TRADE_MARKET_MODE, T1.TRADER, T1.COUNTER_TRADER, T1.COUNTER_CONTACT, T1.SEC_MANAGE_ACCT_ID, T1.F_TRADE_ID, T1.CASH_ID, T1.REMARK, T1.PORTFOLIO_ID, T4.ORDER_ID, T4.ORDER_TYPE, T4.SETTLE_DATE PAY_SETTLE_DATE, T4.MY_ACCT_NO, T4.SETTLE_AMT, T4.CCY PAY_CCY
