FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN STL_PAY_ORDERS T4 ON T1.TOTLE_TRADE_ID = T4.TRADE_ID
WHERE
T1.TOTLE_TRADE_ID = #{bizCode}
T1.P_TOTLE_TRADE_ID = #{bizCode}

select count(1) from FIN_CASH_PLAN
where FINPROD_ID=#{finprodId}
and IS_PAY_INT='N'

select FINPROD_MARKET_ID id, NVL(FINPROD_ABBR, FINPROD_NAME) text, FINPROD_ID object from FIN_PRODUCT
and (instr(FINPROD_MARKET_ID, #{search}) > 0 or instr(FINPROD_ID, #{search}) > 0 or instr(FINPROD_NAME, #{search}) > 0 or instr(FINPROD_ABBR, #{search}) > 0)
and FINPROD_TYPE2 = #{finprodType2}
and PROFIT_TYPE = #{profitType}
